    float target_vyaw = 0.0f;

    if (gesture == "go_forward") {
        if (current_robot_state != "forward") {
            std::cout << "Robot Command: Moving Forward" << std::endl;
            client.Move(MOVE_SPEED_X, 0.0f, 0.0f);
            current_robot_state = "forward";
        }
    } else if (gesture == "turn_left") {
        if (current_robot_state != "turn_left") {
            std::cout << "Robot Command: Turning Left" << std::endl;
            client.Move(0.0f, 0.0f, ROTATE_SPEED);
            current_robot_state = "turn_left";
        }
    } else if (gesture == "turn_right") {
        if (current_robot_state != "turn_right") {
            std::cout << "Robot Command: Turning Right" << std::endl;
            client.Move(0.0f, 0.0f, -ROTATE_SPEED);
            current_robot_state = "turn_right";
        }
    } else if (gesture == "stand_up") {
        if (current_robot_state != "standing") {
            std::cout << "Robot Command: Standing Up" << std::endl;
            client.StandUp();
            current_robot_state = "standing";
        }
    } else if (gesture == "sit_down") {
        if (current_robot_state != "sitting") {
            std::cout << "Robot Command: Sitting Down" << std::endl;
            client.StandDown();
            current_robot_state = "sitting";
        }
    } else if (gesture == "stop" || gesture == "no_gesture") {
        if (current_robot_state != "stopped") {
            std::cout << "Robot Command: Stopping Motion" << std::endl;
            client.StopMove();
            current_robot_state = "stopped";
        }
    } else {
        // Unrecognized gesture, default to stop
        if (current_robot_state != "stopped") {
            std::cout << "Robot Command: Unrecognized gesture, Stopping Motion (" << gesture << ")" << std::endl;
            client.StopMove();
            current_robot_state = "stopped";
        }
    }
}


int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <network_interface_name>" << std::endl;
        return 1; // Exit with an error code
    }

    // Setup signal handler for graceful exit on Ctrl+C.
    signal(SIGINT, sigint_handler);

    // Initialize the channel factory with domain ID 0 and the network interface name
    // argv[1] is a char*, convert it to std::string
    unitree::robot::ChannelFactory::Instance()->Init(0, std::string(argv[1]));
    
    // Initialize SportClient for robot control
    unitree::robot::go2::SportClient sport_client;
    sport_client.SetTimeout(10.0f); // Set communication timeout.
    sport_client.Init();            // Initialize the client.
    sport_client_ptr = &sport_client;  // Assign global pointer for signal handler.

    // Initialize VideoClient for video capture
    unitree::robot::go2::VideoClient video_client;
    video_client.SetTimeout(1.0f); // Set request timeout
    video_client.Init();

    // OpenCV window for displaying video
    cv::namedWindow("Robot Camera Feed", cv::WINDOW_AUTOSIZE);

    std::cout << "Hand Gesture Control Initialized. Press Ctrl+C to stop." << std::endl;
    std::cout << "Video feed will appear in a new window." << std::endl;

    while (running.load()) {
        std::vector<uint8_t> image_data;
        int ret = video_client.GetImageSample(image_data);

        if (ret == 0 && !image_data.empty()) {
            // Decode the JPEG image data into an OpenCV Mat
            cv::Mat raw_image = cv::imdecode(image_data, cv::IMREAD_COLOR);

            if (!raw_image.empty()) {
                // Perform hand gesture detection
                std::string detected_gesture = detectHandGesture(raw_image);

                // Send command to the robot based on detected gesture
                sendRobotCommand(sport_client, detected_gesture);

                // --- Display for debugging ---
                // Add text overlay for detected gesture
                cv::putText(raw_image, "Gesture: " + detected_gesture, cv::Point(50, 50),
                            cv::FONT_HERSHEY_SIMPLEX, 1, cv::Scalar(0, 255, 0), 2, cv::LINE_AA);

                cv::imshow("Robot Camera Feed", raw_image);
            } else {
                std::cerr << "Error: Failed to decode image data." << std::endl;
            }
        } else {
            std::cerr << "Error getting image sample: " << ret << ". Image data empty: " << image_data.empty() << std::endl;
        }

        // Wait a short period to control the processing rate and allow OpenCV to refresh
        int key = cv::waitKey(1); // Wait 1ms for a key press
        if (key == 27) { // ESC key
            running.store(false);
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(20)); // Limit to ~50 FPS
    }

    // Cleanup before exiting.
    std::cout << "Closing video window..." << std::endl;
    cv::destroyAllWindows();
    std::cout << "Exiting program." << std::endl;

    return 0;
}
